import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { authorizeStudioOrigin, enforceStudioRateLimit } from "../_shared/studio-security.ts";

import { requestFlashSpeech } from "../_shared/flash-speech.mjs";

Deno.serve(async (req: Request) => {
  const security = authorizeStudioOrigin(req);
  if (security instanceof Response) return security;
  const { cors } = security;
  const reply = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: cors });

  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
  if (req.method !== "POST") return reply({ error: "Method not allowed" }, 405);
  const blocked = await enforceStudioRateLimit(req, "gemini-tts", cors);
  if (blocked) return blocked;

  try {
    const key = Deno.env.get("GEMINI_API_KEY");
    if (!key) return reply({ error: "GEMINI_API_KEY غير مفعّل." }, 503);
    const body = await req.json();
    const text = String(body?.text || "").trim();
    if (!text) return reply({ error: "لا يوجد نص للتعليق الصوتي." }, 400);
    const voice = String(body?.voice || "Charon");
    const style = String(body?.style || "صحفي وثائقي هادئ وواضح، بالعربية الفصحى الطبيعية، سرعة متوسطة، بلا مبالغة درامية");
    const result = await requestFlashSpeech({ key, text, voice, style });
    return reply(result.body, result.status);
  } catch (error) {
    return reply({ error: error instanceof Error ? error.message : String(error) }, 500);
  }
});

import { createClient } from "npm:@supabase/supabase-js@2";

const DEFAULT_STUDIO_ORIGIN = "https://alnuqtamedia.github.io";
const FUNCTION_NAMES = new Set([
  "gemini-studio",
  "gemini-image",
  "pexels-search",
  "gemini-tts",
]);

export type StudioSecurity = {
  origin: string;
  cors: Record<string, string>;
};

function allowedOrigins(): Set<string> {
  const configured = (Deno.env.get("STUDIO_ALLOWED_ORIGINS") || "")
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean);
  return new Set([DEFAULT_STUDIO_ORIGIN, "https://alnuqta-social-studio.vercel.app", "https://alnuqta-social-studio-git-studio-preview-so-75eddb-alnuqtamedia.vercel.app", "https://alnuqta-social-studio-o5h6qoqub-alnuqtamedia.vercel.app", "https://alnuqta-social-studio-git-dev-studio-produc-9e3d0d-alnuqtamedia.vercel.app", "https://dev-studio-production-20261010-alnuqta-social-studio.alnuqtamedia.workers.dev", "https://8d67a876-alnuqta-social-studio.alnuqtamedia.workers.dev", ...configured]);
}

export function authorizeStudioOrigin(req: Request): StudioSecurity | Response {
  const origin = req.headers.get("origin") || "";
  if (!allowedOrigins().has(origin)) {
    return new Response(JSON.stringify({ error: "origin_not_allowed" }), {
      status: 403,
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        "Vary": "Origin",
      },
    });
  }

  return {
    origin,
    cors: {
      "Access-Control-Allow-Origin": origin,
      "Access-Control-Allow-Headers":
        "authorization, x-client-info, apikey, content-type",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Content-Type": "application/json; charset=utf-8",
      "Vary": "Origin",
    },
  };
}

async function sha256(value: string): Promise<string> {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

export async function enforceStudioRateLimit(
  req: Request,
  functionName: string,
  cors: Record<string, string>,
  limit = 20,
): Promise<Response | null> {
  if (!FUNCTION_NAMES.has(functionName)) {
    return new Response(JSON.stringify({ error: "invalid_function_name" }), {
      status: 500,
      headers: cors,
    });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!supabaseUrl || !serviceRoleKey) {
    return new Response(JSON.stringify({ error: "rate_limit_unavailable" }), {
      status: 503,
      headers: cors,
    });
  }

  const forwarded =
    req.headers.get("cf-connecting-ip") ||
    req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
    "unknown";
  const salt = Deno.env.get("RATE_LIMIT_SALT") || serviceRoleKey.slice(-32);
  const ipHash = await sha256(`${salt}:${forwarded}`);
  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await admin.rpc("check_studio_function_rate_limit", {
    p_function_name: functionName,
    p_ip_hash: ipHash,
    p_limit: limit,
    p_window_seconds: 3600,
  });

  if (error) {
    console.error("studio rate limit failed", error.message);
    return new Response(JSON.stringify({ error: "rate_limit_unavailable" }), {
      status: 503,
      headers: cors,
    });
  }

  const result = Array.isArray(data) ? data[0] : data;
  if (!result?.allowed) {
    const retryAfter = Math.max(1, Number(result?.retry_after_seconds) || 3600);
    return new Response(JSON.stringify({ error: "rate_limit_exceeded" }), {
      status: 429,
      headers: { ...cors, "Retry-After": String(retryAfter) },
    });
  }

  return null;
}

// Only models with a documented free tier. Never fall back to Pro.
export const FREE_TTS_MODELS = ['gemini-2.5-flash-preview-tts', 'gemini-3.1-flash-tts-preview'];
export async function requestFlashSpeech({key,text,voice,style,fetchImpl=fetch}) {
 const attempts=[],deadline=Date.now()+120000;
 const clean=value=>String(value||'').split(key).join('[redacted]').replace(/AIza[\w-]+/g,'[redacted]').slice(0,320);
 for(const model of FREE_TTS_MODELS){
  let response,data;const remaining=deadline-Date.now();if(remaining<1000)break;
  try {
   response=await fetchImpl(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,{
    method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},signal:AbortSignal.timeout(Math.min(90000,remaining)),
    body:JSON.stringify({contents:[{parts:[{text:`اقرأ النص التالي كما هو دون إضافة معلومات. الأداء: ${style}. النص:\n${text}`}]}],generationConfig:{responseModalities:['AUDIO'],maxOutputTokens:8192,speechConfig:{voiceConfig:{prebuiltVoiceConfig:{voiceName:voice}}}}})
   });
   data=await response.json();
  }catch(error){attempts.push({model,status:502,code:error?.name==='TimeoutError'||error?.name==='AbortError'?'provider_timeout':'provider_unavailable'});continue;}
  if(!response.ok){
   const message=String(data?.error?.message||'');
   const limited=response.status===429;
   const delay=(data?.error?.details||[]).find(x=>x?.retryDelay)?.retryDelay;
   attempts.push({model,status:response.status,code:limited?'quota_exceeded':'provider_error',...(message?{message:clean(message)}:{}),...(delay?{retryDelay:delay}:{}),zeroQuota:/limit:\s*0\b/i.test(message)});
   if([401,403].includes(response.status))break;
   continue;
  }
  const candidate=data?.candidates?.[0],finish=candidate?.finishReason;
  const part=candidate?.content?.parts?.find(x=>typeof x?.inlineData?.data==='string'&&x.inlineData.data.length>0);
  if(finish!=='STOP'||!part){attempts.push({model,status:422,code:finish!=='STOP'?'incomplete_audio':'missing_audio',finishReason:finish||'missing'});continue;}
  return {status:200,body:{audio:part.inlineData.data,mimeType:part.inlineData.mimeType||'audio/L16;rate=24000',voice,model}};
 }
 const limited=attempts.some(a=>a.code==='quota_exceeded');
 const error=limited?'حصة الصوت المجانية غير متاحة حالياً من Google. النص محفوظ؛ لم نستخدم Pro أو نفعّل فوترة. راجع الحصة قبل المحاولة التالية.':'لم تُرجع نماذج Flash صوتاً مكتملاً؛ النص محفوظ. لم يُعتمد صوت ناقص.';
 const diagnostic=attempts.filter(a=>!['quota_exceeded'].includes(a.code)).map(a=>`${a.model}: ${a.status} ${a.code}${a.message?' — '+a.message:''}`).join(' | ');
 return {status:limited?429:502,body:{error:limited?error:error+(diagnostic?' '+diagnostic:''),code:limited?'free_tts_quota':'free_tts_unavailable',attempts}};
}
